//! Hash-locked Python CI tools (SUPPLY-07, D1-06).
//!
//! The Python tools (yamllint, ansible-lint, zizmor, check-jsonschema) and all
//! of their dependencies come only from `tools/ci-requirements.txt`, which is
//! generated by `uv pip compile --generate-hashes`. They are installed into a
//! venv built on the pinned python-build-standalone interpreter by the pinned
//! uv, with `--require-hashes --no-deps --only-binary :all:`, so nothing is
//! resolved, built or fetched from anywhere the lock does not name.
//!
//! [`check_requirements_lock`] runs first and refuses anything that is not a
//! `name==version` entry with sha256 hashes, before uv is started.

use std::ffi::OsString;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

use crate::check::{Ctx, Failure};
use crate::tools;

const LOCK_PATH: &str = "tools/ci-requirements.txt";
const LOCK_LABEL: &str = "tools/ci-requirements.txt";

/// Why a logical requirements line was refused, with the package when known.
fn refuse(line_no: usize, package: Option<&str>, reason: &str) -> String {
    match package {
        Some(p) => format!("SUPPLY-07: {LOCK_LABEL}: {p} (line {line_no}): {reason}"),
        None => format!("SUPPLY-07: {LOCK_LABEL}: line {line_no}: {reason}"),
    }
}

/// A requirement line, with continuations joined and comments removed.
struct Logical {
    line_no: usize,
    text: String,
}

/// Drop a `#` comment: a whole-line comment, or one that follows whitespace.
fn strip_comment(line: &str) -> &str {
    let trimmed = line.trim_start();
    if trimmed.starts_with('#') {
        return "";
    }
    let bytes = line.as_bytes();
    for (i, b) in bytes.iter().enumerate() {
        if *b == b'#' && i > 0 && bytes[i - 1].is_ascii_whitespace() {
            return &line[..i];
        }
    }
    line
}

/// Join backslash continuations, drop blank lines and comments.
fn logical_lines(text: &str) -> Vec<Logical> {
    let mut out = Vec::new();
    let mut current: Option<Logical> = None;
    for (idx, raw) in text.lines().enumerate() {
        let line_no = idx + 1;
        let stripped = strip_comment(raw).trim_end();
        let (body, continues) = match stripped.strip_suffix('\\') {
            Some(rest) => (rest.trim_end(), true),
            None => (stripped, false),
        };
        match current.take() {
            Some(mut open) => {
                if !body.trim().is_empty() {
                    open.text.push(' ');
                    open.text.push_str(body.trim());
                }
                if continues && !body.trim().is_empty() {
                    current = Some(open);
                } else {
                    out.push(open);
                }
            }
            None => {
                if body.trim().is_empty() {
                    continue;
                }
                let open = Logical {
                    line_no,
                    text: body.trim().to_string(),
                };
                if continues {
                    current = Some(open);
                } else {
                    out.push(open);
                }
            }
        }
    }
    if let Some(open) = current {
        out.push(open);
    }
    out
}

fn is_name_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || matches!(c, '.' | '_' | '-')
}

/// The package a line starts with, when the line plausibly begins with a name.
fn leading_package(text: &str) -> Option<&str> {
    let end = text
        .char_indices()
        .find(|(_, c)| !is_name_char(*c))
        .map_or(text.len(), |(i, _)| i);
    let name = &text[..end];
    let first = name.chars().next()?;
    if !first.is_ascii_alphanumeric() {
        return None;
    }
    // A scheme such as `https://...` is not a package name.
    if text[end..].starts_with(':') {
        return None;
    }
    Some(name)
}

fn is_version_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || matches!(c, '.' | '_' | '-' | '+' | '!')
}

fn is_sha256_hash(h: &str) -> bool {
    h.len() == 64 && h.bytes().all(|b| matches!(b, b'0'..=b'9' | b'a'..=b'f'))
}

/// Check one logical line; returns a problem description or `None`.
fn check_logical(item: &Logical) -> Option<String> {
    let text = item.text.as_str();
    if text.starts_with('-') {
        return Some(refuse(
            item.line_no,
            None,
            "option lines (index, find-links, editable, nested requirements, stray hash) are not allowed",
        ));
    }
    let package = leading_package(text);
    let mut spec_tokens: Vec<&str> = Vec::new();
    let mut hashes: Vec<&str> = Vec::new();
    for token in text.split_whitespace() {
        if token.starts_with("--hash=") {
            hashes.push(token);
        } else if token.starts_with('-') && token.len() > 1 && token.starts_with("--") {
            return Some(refuse(
                item.line_no,
                package,
                &format!("option `{token}` is not allowed"),
            ));
        } else if hashes.is_empty() {
            spec_tokens.push(token);
        } else {
            return Some(refuse(
                item.line_no,
                package,
                &format!("unexpected `{token}` after the hashes"),
            ));
        }
    }
    let spec = spec_tokens.join(" ");
    let (pin, marker) = match spec.split_once(';') {
        Some((pin, marker)) => (pin.trim(), Some(marker.trim())),
        None => (spec.trim(), None),
    };
    if marker == Some("") {
        return Some(refuse(item.line_no, package, "empty environment marker"));
    }
    let Some((name, version)) = pin.split_once("==") else {
        return Some(refuse(
            item.line_no,
            package,
            "not pinned with `==` (ranges, URLs and bare names are not allowed)",
        ));
    };
    let name_ok = !name.is_empty()
        && name
            .chars()
            .next()
            .is_some_and(|c| c.is_ascii_alphanumeric())
        && name.chars().all(is_name_char);
    let version_ok = !version.is_empty()
        && version
            .chars()
            .next()
            .is_some_and(|c| c.is_ascii_alphanumeric())
        && version.chars().all(is_version_char);
    if !name_ok || !version_ok {
        return Some(refuse(
            item.line_no,
            package,
            "not a plain `name==version` pin",
        ));
    }
    if hashes.is_empty() {
        return Some(refuse(
            item.line_no,
            Some(name),
            "no `--hash=sha256:` (every entry must be hashed)",
        ));
    }
    for hash in hashes {
        let digest = hash.strip_prefix("--hash=sha256:").unwrap_or("");
        if !is_sha256_hash(digest) {
            return Some(refuse(
                item.line_no,
                Some(name),
                &format!("`{hash}` is not `--hash=sha256:` followed by 64 lowercase hex digits"),
            ));
        }
    }
    None
}

/// Check `tools/ci-requirements.txt` text before uv sees it (SUPPLY-07).
///
/// Every requirement must be `name==version`, optionally followed by an
/// environment marker, and carry at least one `--hash=sha256:<64 hex>`.
/// Options, ranges, URLs, editables and nested requirement files fail, and so
/// does a file with no requirements at all.
pub fn check_requirements_lock(text: &str) -> Result<(), Failure> {
    let lines = logical_lines(text);
    if lines.is_empty() {
        return Err(Failure::one(format!(
            "SUPPLY-07: {LOCK_LABEL}: no requirements found"
        )));
    }
    let problems: Vec<String> = lines.iter().filter_map(check_logical).collect();
    if problems.is_empty() {
        Ok(())
    } else {
        Err(Failure::many(problems))
    }
}

/// Environment for every Python-tool child: cleared, plus PATH, HOME, TMPDIR.
fn base_env(cmd: &mut Command, path: Option<OsString>) {
    cmd.env_clear();
    if let Some(p) = path.or_else(|| std::env::var_os("PATH")) {
        cmd.env("PATH", p);
    }
    if let Some(h) = std::env::var_os("HOME") {
        cmd.env("HOME", h);
    }
    if let Some(t) = std::env::var_os("TMPDIR") {
        cmd.env("TMPDIR", t);
    }
}

fn uv_command(uv: &Path, root: &Path) -> Command {
    let mut cmd = Command::new(uv);
    base_env(&mut cmd, None);
    cmd.env("UV_NO_CONFIG", "1")
        .env("UV_PYTHON_DOWNLOADS", "never")
        .env("UV_NO_PROGRESS", "1")
        .env("UV_CACHE_DIR", root.join("target/up-dev-tools/uv-cache"))
        .current_dir(root);
    cmd
}

/// A command for a tool installed in the CI venv, run with a cleared
/// environment. `bin_dir` comes first on PATH so tools find their siblings.
pub fn tool_command(bin_dir: &Path, tool: &str) -> Command {
    let mut path = OsString::from(bin_dir);
    if let Some(old) = std::env::var_os("PATH") {
        path.push(":");
        path.push(old);
    }
    let mut cmd = Command::new(bin_dir.join(tool));
    base_env(&mut cmd, Some(path));
    cmd.env("PYTHONNOUSERSITE", "1")
        .env("PYTHONUTF8", "1")
        .env("PYTHONDONTWRITEBYTECODE", "1");
    cmd
}

fn run_uv(mut cmd: Command, what: &str) -> Result<(), Failure> {
    let status = cmd
        .status()
        .map_err(|e| Failure::one(format!("python-tools: cannot run uv ({what}): {e}")))?;
    if status.success() {
        Ok(())
    } else {
        Err(Failure::one(format!(
            "python-tools: uv {what} failed ({status}); see output above"
        )))
    }
}

/// What the venv directory name and completion marker are derived from (seam; the fix commit
/// adds the interpreter and uv pins).
pub fn venv_key(lock_text: &str, _python_sha256: &str, _uv_sha256: &str) -> String {
    let mut hasher = <sha2::Sha256 as sha2::Digest>::new();
    sha2::Digest::update(&mut hasher, lock_text.as_bytes());
    sha2::Digest::finalize(hasher)
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect()
}

/// The venv directory `ensure_venv` would use for this checkout and host, without installing.
pub fn venv_path(ctx: &Ctx) -> Result<PathBuf, Failure> {
    let text = fs::read_to_string(ctx.root.join(LOCK_PATH))
        .map_err(|e| Failure::one(format!("python-tools: cannot read {LOCK_PATH}: {e}")))?;
    let versions = tools::load_versions(&ctx.root.join("versions.yml"))?;
    let target = tools::host_target()?;
    let python = tools::pinned_sha256(&versions, "python", target)?;
    let uv = tools::pinned_sha256(&versions, "uv", target)?;
    let key = venv_key(&text, &python, &uv);
    Ok(ctx
        .root
        .join("target/up-dev-tools")
        .join(format!("venv-{}", &key[..12])))
}

/// Build (or reuse) the CI venv and return its `bin` directory.
///
/// Path: `<root>/target/up-dev-tools/venv-<first 12 hex of sha256(lock)>`. A
/// `.complete` marker holding the lock hash is written last, so a half-built
/// venv is rebuilt from scratch on the next call.
pub fn ensure_venv(ctx: &Ctx) -> Result<PathBuf, Failure> {
    let lock = ctx.root.join(LOCK_PATH);
    let text = fs::read_to_string(&lock)
        .map_err(|e| Failure::one(format!("python-tools: cannot read {}: {e}", lock.display())))?;
    check_requirements_lock(&text)?;
    let lock_hash = tools::sha256_file(&lock)?;
    let venv = ctx
        .root
        .join("target/up-dev-tools")
        .join(format!("venv-{}", &lock_hash[..12]));
    let bin = venv.join("bin");
    let marker = venv.join(".complete");
    if bin.is_dir() && fs::read_to_string(&marker).is_ok_and(|m| m.trim() == lock_hash) {
        return Ok(bin);
    }
    if venv.exists() {
        fs::remove_dir_all(&venv).map_err(|e| {
            Failure::one(format!(
                "python-tools: cannot remove stale venv {}: {e}",
                venv.display()
            ))
        })?;
    }
    if let Some(parent) = venv.parent() {
        fs::create_dir_all(parent).map_err(|e| {
            Failure::one(format!(
                "python-tools: cannot create {}: {e}",
                parent.display()
            ))
        })?;
    }
    let python = tools::ensure_tool(ctx, "python")?;
    let uv = tools::ensure_tool(ctx, "uv")?;

    let mut create = uv_command(&uv, &ctx.root);
    create
        .args(["venv", "--no-config", "--python"])
        .arg(&python)
        .arg(&venv);
    run_uv(create, "venv")?;

    let mut install = uv_command(&uv, &ctx.root);
    install
        .args(["pip", "install", "--no-config", "--python"])
        .arg(bin.join("python"))
        .args([
            "--require-hashes",
            "--no-deps",
            "--only-binary",
            ":all:",
            "-r",
        ])
        .arg(&lock);
    run_uv(install, "pip install")?;

    fs::write(&marker, format!("{lock_hash}\n")).map_err(|e| {
        Failure::one(format!(
            "python-tools: cannot write {}: {e}",
            marker.display()
        ))
    })?;
    Ok(bin)
}
